style.css:
@-moz-document domain("connect.wavellshs.eq.edu.au") {
/* Global Base & Dark Background */
    body, html, #page, .body, #content, .bg-white {
        background-color: #0b0713 !important;
        color: #e6e0f0 !important;
        font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
    }

    /* Core Layout Panels */
    nav, .sidebar, #sidebar, .header, #header, .footer {
        background-color: #120c22 !important;
        border-color: #bd00ff !important;
        box-shadow: 0 0 12px rgba(189, 0, 255, 0.4) !important;
    }

    /* Component Cards & Panels */
    audio, canvas, progress, video, .card, .panel, .widget, .box, .tile, .component, .section, .list-group-item {
        background-color: #1a1030 !important;
        border: 1px solid #39ff14 !important;
        border-radius: 8px !important;
        box-shadow: 0 0 8px rgba(57, 255, 20, 0.25), inset 0 0 8px rgba(57, 255, 20, 0.1) !important;
        color: #ffffff !important;
        margin-bottom: 15px;
    }

    /* Typography & Glow Accents */
    h1, h2, h3, h4, h5, h6, .title, .heading {
        color: #39ff14 !important;
        text-shadow: 0 0 5px rgba(57, 255, 20, 0.6), 0 0 10px rgba(57, 255, 20, 0.4) !important;
        font-weight: 700;
    }

    /* Links & Menu Navigation */
    a, .nav-link, .menu-item a {
        color: #bd00ff !important;
        text-shadow: 0 0 3px rgba(189, 0, 255, 0.5) !important;
        transition: all 0.3s ease;
    }

    a:hover, .nav-link:hover, .menu-item a:hover {
        color: #39ff14 !important;
        text-shadow: 0 0 8px rgba(57, 255, 20, 0.8) !important;
        text-decoration: none !important;
    }

    /* Highlighting Alternate Items & Subtext */
    span, p, time, .meta, .text-muted, .subtext {
        color: #c9c2db !important;
    }
    
    strong, b {
        color: #00ffff !important;
        text-shadow: 0 0 4px rgba(0, 255, 255, 0.5);
    }

    /* Interactive Inputs & Form Fields */
    input[type="text"], input[type="password"], input[type="search"], textarea, select {
        background-color: #0b0713 !important;
        border: 1px solid #bd00ff !important;
        color: #ffffff !important;
        border-radius: 4px !important;
        box-shadow: inset 0 0 4px rgba(189, 0, 255, 0.2) !important;
    }

    input:focus, textarea:focus, select:focus {
        border-color: #39ff14 !important;
        box-shadow: 0 0 8px rgba(57, 255, 20, 0.6), inset 0 0 4px rgba(57, 255, 20, 0.2) !important;
        outline: none !important;
    }

    /* Action Buttons */
    .btn, button, input[type="submit"] {
        background: linear-gradient(135deg, #bd00ff 0%, #660099 100%) !important;
        border: none !important;
        color: #ffffff !important;
        font-weight: bold !important;
        text-transform: uppercase;
        letter-spacing: 1px;
        box-shadow: 0 0 10px rgba(189, 0, 255, 0.5) !important;
        transition: all 0.2s ease-in-out !important;
    }

    .btn:hover, button:hover, input[type="submit"]:hover {
        background: linear-gradient(135deg, #39ff14 0%, #1f8a0b 100%) !important;
        box-shadow: 0 0 15px rgba(57, 255, 20, 0.7) !important;
        color: #000000 !important;
        cursor: pointer;
    }

    /* Custom Scrollbar */
    ::-webkit-scrollbar {
        width: 10px;
        background-color: #0b0713;
    }
    ::-webkit-scrollbar-thumb {
        background-color: #1a1030;
        border: 2px solid #bd00ff;
        border-radius: 5px;
    }
    ::-webkit-scrollbar-thumb:hover {
        background-color: #39ff14;
    }
}
